#[summary("first_in_sorted: lowest index of x in a non-decreasing array, or -1")]
mod tasks {
    spec fn absent(a: &[i64], x: i64, i: i64) -> bool {
        i == -1 ==> (forall|k: usize| k < a.len() ==> #[trigger] a[k] != x)
    }

    spec fn eq_at(a: &[i64], i: i64, x: i64) -> bool {
        0 <= i && i < a.len() && (forall|k: usize| k == i ==> #[trigger] a[k] == x)
    }

    #[effects(pure)]
    #[uses(absent, eq_at, first_pos, len_ok)]
    fn first_in_sorted(arr: &[i64], x: i64) -> (r: i64)
        requires len_ok(arr),
        ensures absent(arr, x, r), first_pos(arr, x, r),
    {
        let mut j: usize = 0;
        let mut res: i64 = -1;
        while res == -1 && j < arr.len()
            invariant 0 <= j && j <= arr.len(), res != -1 ==> eq_at(arr, res, x) && res < j, forall|k: usize| k < j ==> #[trigger] arr[k] == x ==> res != -1 && res <= k,
            decreases arr.len() - j,
        {
            if arr[j] == x {
                res = j as i64;
            }
            j = j + 1;
        }
        res
    }

    spec fn first_pos(a: &[i64], x: i64, i: i64) -> bool {
        i != -1 ==> eq_at(a, i, x) && (forall|k: usize| k < i ==> #[trigger] a[k] != x)
    }

    spec fn len_ok(a: &[i64]) -> bool {
        a.len() <= i64::MAX
    }
}

