#[summary("isolate: which quantifier forms verify")]
mod probe {
    spec fn all5(t: [usize; 5]) -> bool {
        forall|k: usize| #[trigger] k < 5 ==> t[k] == k
    }

    #[effects(pure)]
    fn h1(n: usize) -> (r: usize)
        requires n <= 3,
        ensures r == n,
    {
        let mut i: usize = 0;
        while i <= n
            invariant i <= n,
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        i
    }

    #[effects(pure)]
    #[uses(le)]
    fn h2(n: usize) -> (r: usize)
        requires n <= 3,
        ensures r == n,
    {
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] le(k, i),
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        i
    }

    #[effects(pure)]
    #[uses(le)]
    fn h3(n: usize) -> (r: usize)
        requires n <= 3,
        ensures r == n,
    {
        let mut t: [usize; 5] = [0; 5];
        t[2] = 7;
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] le(k, i) ==> t[k] == (if k == 2 { 7 } else { 0 }),
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        i
    }

    spec fn le(i: usize, j: usize) -> bool {
        i <= j
    }

    #[effects(pure)]
    fn mk(n: usize) -> (t: [usize; 5]) {
        let mut x: [usize; 5] = [0; 5];
        let mut i: usize = 0;
        while i < 5
            decreases 5 - i,
        {
            x[i] = n;
            i = i + 1;
        }
        x
    }

    #[effects(pure)]
    #[uses(all5)]
    fn pp(t: [usize; 5]) -> (r: usize)
        requires all5(t),
        ensures r == t[2],
    {
        t[2]
    }

    #[effects(pure)]
    fn pq1(n: usize) -> (r: usize)
        requires n <= 4,
        ensures r == n,
    {
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] k <= i ==> k >= 0,
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        i
    }

    #[effects(pure)]
    fn pq2(n: usize) -> (r: usize)
        requires n <= 4,
        ensures r == 9,
    {
        let mut t: [usize; 5] = [0; 5];
        t[3] = 9;
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] k <= i ==> t[k] == (if k == 3 { 9 } else { 0 }),
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        t[3]
    }

    #[effects(pure)]
    fn pq5(n: usize) -> (r: usize)
        requires n <= 4,
        ensures r == n,
    {
        let t: [usize; 5] = mk(n);
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] k <= i ==> t[k] == n,
            decreases n + 1 - i,
        {
            i = i + 1;
        }
        t[0]
    }
}

