#[summary("Levenshtein edit distance between two i64 sequences")]
mod tasks {
    spec fn at(a: &[i64], i: usize) -> i64 {
        if i < a.len() {
            a[i]
        } else {
            0
        }
    }

    spec fn dist(i: usize, j: usize, a: &[i64], b: &[i64]) -> usize
        decreases i + j,
    {
        if i == 0 {
            j
        } else if j == 0 {
            i
        } else {
            smin(smin(dist(i - 1, j, a, b) + 1, dist(i, j - 1, a, b) + 1), dist(i - 1, j - 1, a, b) + (if at(a, i - 1) == at(b, j - 1) { 0 } else { 1 }))
        }
    }

    #[effects(pure)]
    #[uses(at, dist, is_dist, small_enough, smin)]
    fn edit_distance(a: &[i64], b: &[i64]) -> (r: usize)
        requires small_enough(a, b),
        ensures is_dist(a, b, r),
    {
        let n: usize = a.len();
        let m: usize = b.len();
        let mut prev: [usize; 65] = [0; 65];
        let mut cur: [usize; 65] = [0; 65];
        let mut i: usize = 0;
        while i <= n
            invariant forall|k: usize| #[trigger] k < i ==> prev[k] == k,
            decreases n + 1 - i,
        {
            prev[i] = i;
            i = i + 1;
        }
        let mut j: usize = 0;
        while j < m
            invariant forall|k: usize| #[trigger] k <= n ==> prev[k] == dist(k, j, a, b), forall|k: usize| #[trigger] k <= n ==> prev[k] <= k + j, j <= m,
            decreases m - j,
        {
            j = j + 1;
            cur[0] = j;
            i = 0;
            while i < n
                invariant forall|k: usize| #[trigger] k <= i ==> cur[k] == dist(k, j, a, b), forall|k: usize| #[trigger] k <= i ==> cur[k] <= k + j,
                decreases n - i,
            {
                i = i + 1;
                let cost: usize = if a[i - 1] == b[j - 1] {
                    0
                } else {
                    1
                };
                let left: usize = prev[i] + 1;
                let up: usize = cur[i - 1] + 1;
                let diag: usize = prev[i - 1] + cost;
                let best: usize = if left <= up {
                    if left <= diag {
                        left
                    } else {
                        diag
                    }
                } else {
                    if up <= diag {
                        up
                    } else {
                        diag
                    }
                };
                cur[i] = best;
            }
            i = 0;
            while i <= n
                invariant forall|k: usize| #[trigger] k < i ==> prev[k] == cur[k],
                decreases n + 1 - i,
            {
                prev[i] = cur[i];
                i = i + 1;
            }
        }
        prev[n]
    }

    spec fn is_dist(a: &[i64], b: &[i64], r: usize) -> bool {
        r == dist(a.len(), b.len(), a, b)
    }

    spec fn small_enough(a: &[i64], b: &[i64]) -> bool {
        a.len() <= 64 && b.len() <= 64
    }

    spec fn smin(x: usize, y: usize) -> usize {
        if x <= y {
            x
        } else {
            y
        }
    }
}

#[summary("counting sort for values in 0..k")]
mod tasks {
    #[effects(pure)]
    #[uses(count_upto, counted, values_in)]
    fn count_threes(a: &[i64]) -> (r: i64)
        requires values_in(a, 64),
        ensures counted(a, r),
    {
        let mut cnt: [i64; 64] = [0; 64];
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), forall|v: usize| v < 64 ==> #[trigger] (cnt[v] == count_upto(a, i, v)),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            cnt[x as usize] = cnt[x as usize] + 1;
            i = i + 1;
        }
        cnt[3]
    }

    spec fn count_upto(a: &[i64], n: usize, v: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else {
            (if a[n - 1] == v { 1 } else { 0 }) + count_upto(a, n - 1, v)
        }
    }

    spec fn counted(a: &[i64], r: i64) -> bool {
        r == count_upto(a, a.len(), 3)
    }

    spec fn values_in(a: &[i64], k: i64) -> bool {
        forall|i: usize| #[trigger] (i < a.len()) ==> 0 <= a[i] && a[i] < k
    }
}

#[summary("check whether a ±1 parenthesis sequence is properly nested")]
mod tasks {
    #[effects(pure)]
    #[uses(balanced_spec, prefix_sum)]
    fn balanced(p: &[i64]) -> (r: bool)
        requires vals_domain(p),
        ensures r == balanced_spec(p),
    {
        let mut i: usize = 0;
        let mut depth: i64 = 0;
        let mut ok: bool = true;
        while i < p.len() && ok
            invariant i <= p.len(), prefix_sum(p, i) == depth, ok == (0 <= depth), depth <= i, ok ==> (forall|k: usize| #[trigger] (k <= i ==> prefix_sum(p, k) >= 0)),
            decreases p.len() - i,
        {
            if p[i] == 1 {
                depth = depth + 1;
            } else {
                depth = depth - 1;
                if depth < 0 {
                    ok = false;
                }
            }
            i = i + 1;
        }
        ok && depth == 0
    }

    spec fn balanced_spec(p: &[i64]) -> bool {
        prefix_sum(p, p.len()) == 0 && (forall|k: usize| k <= p.len() ==> #[trigger] prefix_sum(p, k) >= 0)
    }

    spec fn prefix_sum(p: &[i64], k: usize) -> i64
        decreases k,
    {
        if k == 0 {
            0
        } else if k <= p.len() {
            prefix_sum(p, k - 1) + p[k - 1]
        } else {
            prefix_sum(p, p.len())
        }
    }

    spec fn vals_domain(p: &[i64]) -> bool {
        p.len() <= 1000 && (forall|j: usize| #[trigger] p[j] == 1 || p[j] == -1)
    }
}
